import{describe,it,expect,beforeAll}from"vitest";import{readFileSync}from"node:fs";import{resolve,dirname}from"node:path";import{fileURLToPath}from"node:url";const __dirname=dirname(fileURLToPath(import.meta.url));function loadDurandData(){const e=readFileSync(resolve(__dirname,"../../durand-cup-explorer/durand-data.js"),"utf-8");return new Function(e+"\nreturn { DURAND_INFO, THREE_TROPHIES, SUCCESSFUL_CLUBS, HISTORIC_VENUES, TOURNAMENT_MILESTONES, REFERENCES };")()}describe("Durand Cup Explorer — Data Tests",()=>{let e;beforeAll(()=>{e=loadDurandData()}),describe("DURAND_INFO metadata",()=>{it("contains correct Durand Cup metadata and founding year 1888",()=>{expect(e.DURAND_INFO.id).toBe("durand-cup"),expect(e.DURAND_INFO.title).toContain("Durand Cup"),expect(e.DURAND_INFO.foundedYear).toBe("1888 CE"),expect(e.DURAND_INFO.founder).toContain("Durand")}),it("has quickStats array with 6 items",()=>{expect(Array.isArray(e.DURAND_INFO.quickStats)).toBe(!0),expect(e.DURAND_INFO.quickStats.length).toBe(6)})}),describe("THREE_TROPHIES & SUCCESSFUL_CLUBS",()=>{it("contains 3 iconic trophies and Mohun Bagan / East Bengal champions data",()=>{expect(Array.isArray(e.THREE_TROPHIES)).toBe(!0),expect(e.THREE_TROPHIES.length).toBe(3),expect(Array.isArray(e.SUCCESSFUL_CLUBS)).toBe(!0);const t=e.SUCCESSFUL_CLUBS.find(e=>e.club.includes("Mohun Bagan"));expect(t).toBeDefined(),expect(t.titles).toBe(17)})}),describe("HISTORIC_VENUES & REFERENCES",()=>{it("contains historic venues and reference citations",()=>{expect(Array.isArray(e.HISTORIC_VENUES)).toBe(!0),expect(e.HISTORIC_VENUES.length).toBeGreaterThanOrEqual(3),expect(Array.isArray(e.REFERENCES)).toBe(!0),expect(e.REFERENCES.length).toBeGreaterThanOrEqual(2)})})});